    {
      "symbol": "A08",
      "target_weight": 0.08,
      "rationale": "Lowest volatility in the book (9.7%) and narrow interval (4.58%); hold near baseline 8.07% as the stable anchor of the financials group.",
      "confidence": 0.5
    },
    {
      "symbol": "A09",
      "target_weight": 0.145,
      "rationale": "Narrowest 5d interval (3.54%) — the most reliable forecast in the book — plus 11% vol. Overweight bonds +4.1pp above baseline (10.44%) as defensive ballast for the high-vol equity sleeve; well within the +15pp increase allowance and the 25% ETF cap.",
      "confidence": 0.55
    },
    {
      "symbol": "A05",
      "target_weight": 0.045,
      "rationale": "Gold diversifier: wide interval (8.2%) and 25.4% vol limit size despite strong 20d momentum (+13.5%); hold near baseline 4.49%.",
      "confidence": 0.5
    },
    {
      "symbol": "A01",
      "target_weight": 0.0,
      "rationale": "Widest 5d interval (11.8%) with 33% vol and negative 1d/5d returns (-1.6%/-3.6%); stay at zero vs baseline 3.14% — highest-uncertainty name in the book.",
      "confidence": 0.6
    },
    {
      "symbol": "A15",
      "target_weight": 0.056,
      "rationale": "Financials stock, moderate interval (6.7%), 14.3% vol, flat recent returns; near baseline 5.51%. Financials group total ~13.6%, under the 30% cap.",
      "confidence": 0.5
    },
    {
      "symbol": "A13",
      "target_weight": 0.043,
      "rationale": "Energy stock, wide interval (8.8%), 24.9% vol, negative 5d (-4.0%); near baseline 4.18%.",
      "confidence": 0.5
    },
    {
      "symbol": "A07",
      "target_weight": 0.0,
      "rationale": "Widest interval (11.8%), highest vol (41.9%), and negative returns across 1d/5d/20d; stay at zero vs baseline 3.12%. Clearest risk-based exclusion in the book.",
      "confidence": 0.6
    },
    {
      "symbol": "A14",
      "target_weight": 0.02,
      "rationale": "Extreme vol (59% ann.) and wide interval (9.4%) outweigh the strong 20d momentum (+14.8%); hold below baseline 3.92% at 2%, matching current 1.99%.",
      "confidence": 0.55
    }
  ],
  "cash_weight": 0.127
}

